solution.javascript:
function letterCombinations(digits) {
  if (!digits.length) return [];
  const map = { '2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz' };
  const result = [];
  function backtrack(i, path) {
    if (i === digits.length) { result.push(path); return; }
    for (const c of map[digits[i]]) backtrack(i + 1, path + c);
  }
  backtrack(0, '');
  return result;
}

solution.cpp:
vector<string> letterCombinations(string digits) {
    if (digits.empty()) return {};
    vector<string> map = {"","","abc","def","ghi","jkl","mno","pqrs","tuv","wxyz"};
    vector<string> result;
    function<void(int,string)> bt = [&](int i, string path) {
        if (i == digits.size()) { result.push_back(path); return; }
        for (char c : map[digits[i]-'0']) bt(i+1, path+c);
    };
    bt(0, "");
    return result;
}
